  "city.doppel-upper.description": "The highest floor of Doppel's research lab. The people who decide the purpose of the research sit here.",
  "city.doppel-upper.displayName": "Doppel · Upper Echelon",
  "city.rust-works.description": "A vast foundry at the heart of Rust. Design and repair of research equipment all gather in one place.",
  "city.rust-works.displayName": "Rust · Central Foundry",
  "city.odidi-embassy.description": "A reception room where Odidi, the city that studies dreams, receives outside guests. The proposals always come from them first.",
  "city.odidi-embassy.displayName": "Odidi · Diplomatic Reception Room",
  "journal.interaction-doppel-lab-01.title": "Diary of the Dispatch That Never Returned",
  "journal.interaction-doppel-lab-01.body": "The diary of a researcher once dispatched to Eternal. The last page is a single line, \"The replacement staff has arrived,\" and the signature box beneath it is empty.",
  "city.department.exchange": "Exchange Office",
  "city.department.council": "Council",
  "city.doppel-parlor.displayName": "Doppel · Central Research Lab Parlor",
  "shopClerk.obi.name": "Obi",
  "shopClerk.protia.name": "Protia",
  "shopClerk.haine.name": "Haine",
  "journal.interaction-doppel-01.title": "Placard of the Blue Corridor",
  "journal.interaction-doppel-01.body": "The greenhouse's first notice board still carries a line asking that restored bodies be welcomed as new neighbors, not as a spectacle.",
  "journal.interaction-doppel-02.title": "The Greeting That Repeats",
  "bond.torika.0": "Who are you?",
  "bond.torika.1": "You came again.",
  "bond.torika.2": "You can stay beside me.",
  "bond.torika.3": "What should we do today?",
  "bond.torika.4": "I know your footsteps.",
  "bond.torika.5": "It's calm when we're together.",
  "bond.torika.6": "I'll guard your back.",
  "bond.torika.7": "I was waiting.",
  "bond.torika.8": "I feel safe when you come.",
  "bond.torika.9": "I'll go with you to the end.",
  "bond.torika.10": "I'll protect our garden myself.",
  "bond.rex.0": "Don't touch me.",
  "bond.rex.1": "Not afraid, are you?",
  "bond.rex.2": "A little interesting.",
  "bond.rex.3": "Come to the next hunt too.",
  "bond.rex.4": "I've memorized your scent.",
  "bond.rex.5": "Don't leave my side.",
  "bond.rex.6": "Anything that comes for you, I bite.",
  "bond.rex.7": "You're late again today.",
  "bond.rex.8": "I prefer your voice to orders.",
  "bond.rex.9": "You are my only pack.",
  "bond.rex.10": "I will be on your side forever.",
  "bond.spino.0": "…What is it?",
  "bond.spino.1": "I miss the water.",
  "bond.spino.2": "It's fine to stay quiet.",
  "bond.spino.3": "Tell me more of your story.",
  "bond.spino.4": "The waves are calm today.",
  "bond.spino.5": "I like walking together.",
  "bond.spino.6": "If it's dangerous, get behind me.",
  "bond.spino.7": "I knew you would come.",
  "bond.spino.8": "I'm used to this city now.",
  "bond.spino.9": "Your side is my water.",
  "bond.spino.10": "Let's flow anywhere together.",
  "bond.generic.0": "It's still a little unfamiliar.",
  "bond.generic.1": "We met again today.",
  "bond.generic.2": "I'm getting used to it, bit by bit.",
  "bond.generic.3": "Let's go on a mission together.",
  "bond.generic.4": "I'm glad when you come.",
  "bond.generic.5": "You can stay beside me.",
  "bond.generic.6": "I'll help again this time.",
  "bond.generic.7": "I was waiting.",
  "bond.generic.8": "We're good companions.",
  "bond.generic.9": "I want to stay together a long time.",
  "bond.generic.10": "I'm counting on you from here on.",
